'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let gameState='ready',gameSession=null,gameStep=0,gameMistakes=0,gameCombo=0,gameMaxCombo=0,gameElapsed=0,gameDanger=0,gameLastTick=0,gameTimer=null,gameAudio,gameMaster,gameVoices=new Set(),gameBests={};
try{const saved=JSON.parse(localStorage.getItem('qinshi-chase-bests')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))gameBests=saved}catch{}
const gameClock=ms=>`${Math.floor(ms/60000).toString().padStart(2,'0')}:${Math.floor(ms/1000%60).toString().padStart(2,'0')}`;
const chosenSong=()=>chaseSongs.find(s=>s.id===$('#chase-song').value)||chaseSongs[0];
const chosenLength=()=>[1,2,4].includes(+$('#chase-length').value)?+$('#chase-length').value:2;
const chosenDifficulty=()=>['relaxed','normal','fast'].includes($('#chase-difficulty').value)?$('#chase-difficulty').value:'relaxed';
const bestKey=()=>`${chosenSong().id}:${chosenLength()}:${chosenDifficulty()}`;
function bestText(){const b=gameBests[bestKey()];return b&&Number.isFinite(b.accuracy)&&Number.isFinite(b.elapsed)?`${b.accuracy}% · ${gameClock(b.elapsed)}`:'还没挑战过'}
function audioReady(){if(!gameAudio){gameAudio=new AudioContext();gameMaster=gameAudio.createGain();const compressor=gameAudio.createDynamicsCompressor();gameMaster.gain.value=+$('#game-volume').value/100;gameMaster.connect(compressor);compressor.connect(gameAudio.destination)}if(gameAudio.state==='suspended')gameAudio.resume().catch(()=>{$('#game-feedback').textContent='浏览器尚未允许声音，请再次点击输入框。'});return gameAudio}
function playGameNote(m){const ctx=audioReady(),t=ctx.currentTime,g=ctx.createGain();g.connect(gameMaster);const tone=$('#game-tone').value,partials=tone==='bell'?[[1,1],[2.76,.18],[5.4,.05]]:tone==='electric'?[[1,.85],[2,.27],[3,.08]]:[[1,1],[2,.22],[3,.08]];const nodes=partials.map(([r,v])=>{const o=ctx.createOscillator(),a=ctx.createGain();o.frequency.value=440*2**((m-69)/12)*r;a.gain.value=.15*v;o.connect(a);a.connect(g);o.start(t);o.stop(t+.75);return o});g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.85,t+.008);g.gain.exponentialRampToValueAtTime(.12,t+.2);g.gain.exponentialRampToValueAtTime(.0001,t+.72);const voice={nodes,g};gameVoices.add(voice);if(gameVoices.size>12){const oldest=gameVoices.values().next().value;oldest.nodes.forEach(o=>o.stop(ctx.currentTime));oldest.g.disconnect();gameVoices.delete(oldest)}setTimeout(()=>{g.disconnect();gameVoices.delete(voice)},800)}
function quietGame(){if(gameAudio)for(const v of gameVoices){v.nodes.forEach(o=>o.stop(gameAudio.currentTime));v.g.disconnect()}gameVoices.clear()}
function makeSession(){const song=chosenSong(),rounds=chosenLength();return {song,rounds,difficulty:chosenDifficulty(),notes:Array.from({length:rounds},()=>song.notes).flat(),keys:Array.from({length:rounds},()=>song.keys).flat()}}
function resetGame(){clearInterval(gameTimer);gameTimer=null;quietGame();gameState='ready';gameSession=makeSession();gameStep=gameMistakes=gameCombo=gameMaxCombo=gameElapsed=gameDanger=0;$('#game-result').hidden=true;$('#typing-input').value='';$('#game-feedback').textContent='只需按对应字母，不用输入曲名。';$('#scene-message').textContent='警官准备好了，等你弹响第一个音符。';$('#catch-celebration').hidden=true;$('.chase-world').classList.remove('won','lost');$('#chase-song-description').textContent=`${gameSession.song.cover} ${gameSession.song.form} · 单遍 ${gameSession.song.notes.length} 个音符`;const target=gameSession.difficulty==='fast'?75:45;$('#chase-length-description').textContent=`共 ${gameSession.notes.length} 次按键 · 按 ${target} 键/分约 ${Math.ceil(gameSession.notes.length/target)} 分钟（含找键时间会更长）`;$('#game-difficulty-note').textContent=gameSession.difficulty==='relaxed'?'轻松模式：不会失败，不限时；每次弹对，警察就更近一点。':`挑战模式：目标每分钟 ${target} 个正确按键；前 5 秒准备，之后停顿或失误会增加逃跑风险。`;renderGame();}
function renderGame(){const session=gameSession,total=session.notes.length,progress=gameStep/total;const accuracy=gameStep+gameMistakes?Math.round(gameStep/(gameStep+gameMistakes)*100):null;$('#game-progress').textContent=`${gameStep} / ${total}`;$('#game-accuracy').textContent=accuracy===null?'—':accuracy+'%';$('#game-combo').textContent=String(gameCombo);$('#game-time').textContent=`${gameClock(gameElapsed)} · ${gameElapsed>0?Math.round(gameStep/(gameElapsed/60000)):0} 键/分`;$('#game-best').textContent=bestText();$('#game-progress-bar').style.width=progress*100+'%';$('.progress-track').setAttribute('aria-valuenow',String(Math.round(progress*100)));$('#game-pass').textContent=`第 ${Math.min(session.rounds,Math.floor(gameStep/session.song.keys.length)+1)} / ${session.rounds} 遍`;const distance=gameState==='won'?0:Math.max(1,Math.round((1-progress)*140+gameDanger*.6));$('#chase-distance').textContent=gameState==='ready'?'准备出发':gameState==='won'?'成功追上！':gameState==='lost'?'这次小偷跑远了':`还差 ${distance} 米${session.difficulty==='relaxed'?'':` · 风险 ${Math.round(gameDanger)}%`}`;$('#police').style.left=(12+progress*48)+'%';$('#thief').style.left=(gameState==='won'?65:Math.min(89,75+gameDanger*.13))+'%';$('.chase-world').classList.toggle('running',gameState==='running');$('#game-start').disabled=gameState==='running';$('#game-start').textContent=gameState==='paused'?'继续追逐 →':['won','lost','stopped'].includes(gameState)?'再来一局 →':'开始追逐 →';$('#game-pause').disabled=gameState!=='running';$('#game-stop').disabled=!['running','paused'].includes(gameState);$('#typing-input').disabled=gameState!=='running';['#chase-song','#chase-length','#chase-difficulty'].forEach(s=>$(s).disabled=['running','paused'].includes(gameState));$('#typing-input').placeholder=gameState==='running'?'输入最左侧高亮字母…':gameState==='paused'?'已暂停，点击“继续追逐”':'点击“开始追逐”，准备好双手…';$('#typing-notes').innerHTML=session.keys.slice(gameStep,gameStep+9).map((k,i)=>`<div class="typing-note ${i===0?'current':''}"><b>${k.toUpperCase()}</b><small>${['Do','Re','Mi','Fa','Sol','La','Si','Do↑','Re↑','Mi↑','Fa↑','Sol↑'][chaseNoteKeys.indexOf(k)]}</small></div>`).join('');if(gameStep===total)$('#typing-notes').innerHTML='<div class="all-notes-done">✓ 整段旋律，都是你的声音。</div>';$$('[data-chase-key]').forEach(b=>b.classList.toggle('target',b.dataset.chaseKey===session.keys[gameStep]));}
function gameTick(){if(gameState!=='running')return;const now=performance.now(),delta=Math.max(0,Math.min(1000,now-gameLastTick));gameLastTick=now;gameElapsed+=delta;if(gameSession.difficulty!=='relaxed'&&gameElapsed>5000){const rate=gameSession.difficulty==='fast'?75:45;gameDanger=Math.min(100,gameDanger+delta/1000*rate/30);if(gameDanger>=100){finishGame(false);return}}renderStats();}
function renderStats(){$('#thief').style.left=Math.min(89,75+gameDanger*.13)+'%';$('#game-time').textContent=`${gameClock(gameElapsed)} · ${gameElapsed>0?Math.round(gameStep/(gameElapsed/60000)):0} 键/分`;if(gameSession.difficulty!=='relaxed')$('#chase-distance').textContent=`还差 ${Math.max(1,Math.round((1-gameStep/gameSession.notes.length)*140+gameDanger*.6))} 米 · 风险 ${Math.round(gameDanger)}%`;}
function startGame(){if(gameState==='running')return;if(gameState!=='paused')resetGame();audioReady();gameState='running';gameLastTick=performance.now();clearInterval(gameTimer);gameTimer=setInterval(gameTick,100);$('#scene-message').textContent='跟着高亮字母，一起把旋律弹完！';$('#game-feedback').textContent='按对一个，向前一步。';renderGame();$('#typing-input').focus()}
function pauseGame(message='已暂停，准备好后继续。'){if(gameState!=='running')return;gameTick();if(gameState!=='running')return;gameState='paused';clearInterval(gameTimer);gameTimer=null;quietGame();$('#scene-message').textContent=message;$('#game-feedback').textContent='暂停不计时，也不会增加逃跑风险。';renderGame()}
function stopGame(){if(['running','paused'].includes(gameState)){clearInterval(gameTimer);gameTimer=null;quietGame();gameState='stopped';$('#scene-message').textContent='这局已停止。可以换首歌，重新出发。';$('#game-feedback').textContent='进度已停止，本局不会记作完成。';renderGame()}}
function typeGameKey(key){if(gameState!=='running')return;key=key.toLowerCase();if(key.length!==1)return;gameTick();if(gameState!=='running')return;const expected=gameSession.keys[gameStep];if(key!==expected){gameMistakes++;gameCombo=0;gameDanger=Math.min(gameSession.difficulty==='relaxed'?85:100,gameDanger+7);$('#game-feedback').textContent=`再试一次，下一音按 ${expected.toUpperCase()}。`;$('.typing-console').classList.remove('wrong');void $('.typing-console').offsetWidth;$('.typing-console').classList.add('wrong');if(gameDanger>=100){finishGame(false);return}renderGame();return}playGameNote(gameSession.notes[gameStep]);gameStep++;gameCombo++;gameMaxCombo=Math.max(gameCombo,gameMaxCombo);gameDanger=Math.max(0,gameDanger-2);$('#game-feedback').textContent=gameCombo%10===0?`连续 ${gameCombo} 个正确！警官加速啦。`:['就是这个音！','做得好，再近一步。','继续，旋律正在发生。'][gameStep%3];$('#scene-message').textContent=gameStep%gameSession.song.keys.length===0?'这一遍弹完啦，继续下一遍！':`已弹对 ${gameStep} 个音，小偷跑不远啦。`;renderGame();if(gameStep===gameSession.keys.length)finishGame(true)}
function finishGame(won){clearInterval(gameTimer);gameTimer=null;gameState=won?'won':'lost';if(!won)quietGame();const accuracy=Math.round(gameStep/Math.max(1,gameStep+gameMistakes)*100);if(won){const key=bestKey(),old=gameBests[key];if(!old||!Number.isFinite(old.accuracy)||accuracy>old.accuracy||(accuracy===old.accuracy&&gameElapsed<old.elapsed)){gameBests[key]={accuracy,elapsed:gameElapsed,combo:gameMaxCombo};try{localStorage.setItem('qinshi-chase-bests',JSON.stringify(gameBests))}catch{}}}$('.chase-world').classList.add(won?'won':'lost');$('#catch-celebration').hidden=!won;$('#scene-message').textContent=won?'抓到啦！谢谢你的音符，今天的小镇又安静了。':'小偷暂时跑远了。放松一下，我们可以再来！';$('#result-icon').textContent=won?'★':'♫';$('#result-title').textContent=won?'抓到小偷，也弹完了一首歌！':'别着急，下一次会更熟练。';$('#result-copy').textContent=`《${gameSession.song.name}》 · ${gameStep} / ${gameSession.keys.length} 个音 · 准确率 ${accuracy}% · 最长连击 ${gameMaxCombo} · 用时 ${gameClock(gameElapsed)}`;$('#game-feedback').textContent=won?'挑战完成！可以再练一次，或换一首歌。':'试试轻松模式，先熟悉这首歌的琴键。';$('#game-result').hidden=false;renderGame();}
$('#chase-song').innerHTML=chaseSongs.map(s=>`<option value="${s.id}">${s.cover} ${s.name} · ${s.level}</option>`).join('');['#chase-song','#chase-length','#chase-difficulty'].forEach(s=>$(s).onchange=resetGame);$('#game-start').onclick=startGame;$('#game-pause').onclick=()=>pauseGame();$('#game-stop').onclick=stopGame;$('#game-restart').onclick=()=>{resetGame();startGame()};$('#result-retry').onclick=()=>{resetGame();startGame()};$('#result-change').onclick=()=>{resetGame();$('#chase-song').focus();$('.game-config').scrollIntoView({behavior:'smooth',block:'center'})};
$('#typing-input').addEventListener('keydown',e=>{if(e.code==='Escape'){e.preventDefault();pauseGame();return}if(e.repeat){e.preventDefault();return}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.length===1){e.preventDefault();typeGameKey(e.key)}});$('#typing-input').addEventListener('input',e=>{const value=e.target.value;e.target.value='';if(!e.isComposing&&value.length===1)typeGameKey(value)});$('#typing-input').addEventListener('paste',e=>e.preventDefault());$('#typing-input').addEventListener('compositionend',()=>{$('#typing-input').value='';$('#game-feedback').textContent='请切换到英文输入法，按字母琴键。'});
window.addEventListener('keydown',e=>{if(e.code==='Escape'&&gameState==='running')pauseGame()});window.addEventListener('blur',()=>pauseGame('窗口已离开，追逐自动暂停。'));document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseGame('离开页面时自动暂停，回来继续。')});window.addEventListener('pagehide',()=>{clearInterval(gameTimer);quietGame()});$('#game-volume').oninput=()=>{audioReady();gameMaster.gain.setTargetAtTime(+$('#game-volume').value/100,gameAudio.currentTime,.02)};
$('#rules-button').onclick=()=>{pauseGame();$('#rules-dialog').showModal()};$('#close-rules').onclick=()=>$('#rules-dialog').close();
$('#chase-keyboard').innerHTML=chaseNoteKeys.map((k,i)=>`<button data-chase-key="${k==='"'?'&quot;':k}" aria-label="弹奏 ${k.toUpperCase()}"><small>${['C4','D4','E4','F4','G4','A4','B4','C5','D5','E5','F5','G5'][i]}</small><b>${k.toUpperCase()}</b></button>`).join('');$$('[data-chase-key]').forEach(b=>b.onpointerdown=e=>{e.preventDefault();if(gameState==='running'){typeGameKey(b.dataset.chaseKey);$('#typing-input').focus()}});resetGame();
$('#game-tone').onchange=()=>{if(gameState==='running')$('#typing-input').focus()};$('#game-volume').onpointerup=()=>{if(gameState==='running')$('#typing-input').focus()};
